import ctypes as c
from ctypes import wintypes as w
import sys,time

class HC(c.Structure):
    _fields_=(("cbSize",w.UINT),("dwFlags",w.DWORD),("lpszDefaultScheme",w.LPWSTR))
u=c.WinDLL("user32",use_last_error=True)
def state():
    x=HC(); x.cbSize=c.sizeof(x)
    if not u.SystemParametersInfoW(0x0042,x.cbSize,c.byref(x),0):
        raise OSError(c.get_last_error(),"SPI_GETHIGHCONTRAST failed")
    return bool(x.dwFlags&1),x.lpszDefaultScheme
def key(vk,up=False):
    u.keybd_event(vk,0,2 if up else 0,0)
def chord():
    for vk in (0xA4,0xA0,0x2C): key(vk)
    for vk in (0x2C,0xA0,0xA4): key(vk,True)
def fg():
    h=u.GetForegroundWindow()
    title=c.create_unicode_buffer(512); cls=c.create_unicode_buffer(128)
    u.GetWindowTextW(h,title,len(title)); u.GetClassNameW(h,cls,len(cls))
    return h,title.value,cls.value
target=sys.argv[1].lower()=="on"
before,scheme=state()
print("HC_HOTKEY_BEFORE",before,repr(scheme),flush=True)
if before!=target:
    chord()
    time.sleep(1.5)
    now,_=state()
    if now!=target:
        h,title,cls=fg()
        print("HC_HOTKEY_FOREGROUND",hex(h),repr(title),repr(cls),flush=True)
        if cls=="#32770":
            key(0x0D); key(0x0D,True)
    end=time.monotonic()+12
    while time.monotonic()<end:
        now,scheme=state()
        if now==target: break
        time.sleep(.5)
after,scheme=state()
print("HC_HOTKEY_AFTER",after,repr(scheme),flush=True)
if after!=target:
    raise SystemExit("High Contrast hotkey toggle did not reach requested state")

